#!/bin/sh
# Generated by buildhost.
#
# {{.Pkg}} is an Actually Portable Executable: it rewrites its own file
# the first time it runs. A root-owned binary in /usr/bin cannot do that for
# an ordinary user, so run a per-user writable copy instead.
real={{.Real}}
dir="${XDG_CACHE_HOME:-${HOME:-/tmp}/.cache}/buildhost/{{.Pkg}}/{{.Version}}"
bin="$dir/{{.Pkg}}"
if [ ! -x "$bin" ]; then
	mkdir -p "$dir" 2>/dev/null || exec "$real" "$@"
	tmp="$bin.$$"
	if cp "$real" "$tmp" 2>/dev/null && chmod 0755 "$tmp" 2>/dev/null && mv "$tmp" "$bin" 2>/dev/null; then
		:
	else
		rm -f "$tmp" 2>/dev/null
		exec "$real" "$@"
	fi
fi
exec "$bin" "$@"
